import{_ as s,l as o,o as e,c as l,v as r,p as n,x as t,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"令牌桶与整形","description":"","frontmatter":{"title":"令牌桶与整形","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/token-bucket-shaping.md","filePath":"cs/token-bucket-shaping.md","lastUpdated":1789023840000}'),h={name:"cs/token-bucket-shaping.md"};function f(u,a,_,b,B,E){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="令牌桶与整形" tabindex="-1">令牌桶与整形 <a class="header-anchor" href="#令牌桶与整形" aria-label="Permalink to &quot;令牌桶与整形&quot;">​</a></h1><div class="epigraph"><p>速率 $r$、桶深 $b$ 限制平均与突发；整形等令牌，监管丢或染色，给 WFQ 的延迟界提供入口合同。</p><footer>—— 据 Turner 令牌桶通识；RFC 2697 / 2698 srTCM/trTCM；Parekh–Gallager 条件整理</footer></div><p><a href="/cs/wfq-fair-queue">上一课</a> 的延迟界要流被整形。缺口是<strong>令牌桶</strong>：平均速率、突发、整形 vs 监管。本课不把 DSCP 码点写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>接入合同写 100 Mb/s，但缓冲允许微突发。令牌以 \\(r\\) 产生，桶最多 \\(b\\)，发 \\(L\\) 字节耗 \\(L\\) 令牌。无令牌：整形器等待（加延迟），监管器丢或标红。双速三色（RFC 2698）给黄/红。与 AIMD：桶在边缘，cwnd 在端，两者叠加。BDP 突发 \\(b\\) 过小会切峰，过大则瞬间打满下游浅队列（incast 亲戚）。</p><p>不要把令牌桶写成加密代币。</p><p><span class="marginnote">RFC 4115 等更新变体。本课钉 \\((r,b)\\)。漏桶对照：恒定出速率。</span></p><h3 id="合同" tabindex="-1">\\((r,b)\\) 合同 <a class="header-anchor" href="#合同" aria-label="Permalink to &quot;$(r,b)$ 合同&quot;">​</a></h3><p>整形等令牌加延迟，监管丢或染色。\\(b\\) 无限等于没限。TSO 大段看起来像突发。测速可能只是在量桶。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：整形 / 监管 / 优先级。画：包 → 扣令牌 → 过或等或丢。与 PAUSE：令牌桶是端或边缘政策，PAUSE 是邻跳反压。</p>',11)),(e(),n(c,null,{default:t(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOK%5B%22%E4%BB%A5%20r%20%E4%BA%A7%E7%94%9F%E4%BB%A4%E7%89%8C%22%5D%20--%3E%20B%5B%22%E6%A1%B6%E6%B7%B1%20b%22%5D%0A%20%20PKT%5B%22%E5%8C%85%E9%95%BF%20L%22%5D%20--%3E%20B%0A%20%20B%20--%3E%20PASS%5B%22%E6%9C%89%E4%BB%A4%E7%89%8C%E5%88%99%E5%8F%91%22%5D%0A%20%20B%20--%3E%20WAIT%5B%22%E6%95%B4%E5%BD%A2%E7%AD%89%E5%BE%85%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>WFQ+令牌桶 ⇒ 端到端延迟上界（理论）。DiffServ 用类桶而不是每用户桶。卫星 \\(r\\) 小，\\(b\\) 要能装一个 BDP 突发否则永远喂不饱。TSO 大段会一次扣很多令牌，看起来像突发。</p><p>测速：iperf 被边缘桶限，不是路径 \\(C\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入层次令牌桶的全部 classful qdisc。DiffServ 是下一课。后课默认：\\((r,b)\\) 描述突发约束；整形加延迟，监管丢/染色。</p><p>合同写 \\(r\\) 却把 \\(b\\) 设成无限，等于没限。</p><p>上一课留下的缺口在本课收口；「令牌桶与整形」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/diffserv-qos">DiffServ</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>令牌桶钉平均与突发。</li><li>整形等待，监管丢或着色。</li><li>与 WFQ 一起才有延迟合同。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 2697/2698；Parekh–Gallager。</li></ul>',10))])}const T=s(h,[["render",f]]);export{A as __pageData,T as default};
